<?php
$table=(string)($_GET['t']??'carrier');$catalog->check($table);$cols=$catalog->columns($table);$foreign=$catalog->foreign($table);$canWrite=Auth::can($user,$catalog->right($table))&&!in_array($table,Catalog::READONLY,true);
$readCols=array_values(array_filter($cols,fn($c)=>!in_array($c['Field'],['id','password_hash','entity_id'],true)));$where=[];$params=[];
if(!empty($_GET['q'])){foreach($readCols as $c)if(str_starts_with($c['Type'],'varchar')||str_starts_with($c['Type'],'text')){$where[]='`'.$c['Field'].'` LIKE ?';$params[]='%'.$_GET['q'].'%';}}
$conditions=$where?'('.implode(' OR ',$where).')':'1=1';
foreach([...array_keys($foreign),'status'] as $key)if(!empty($_GET['f_'.$key])&&in_array($key,array_column($cols,'Field'),true)){$conditions.=' AND `'.$key.'`=?';$params[]=$_GET['f_'.$key];}
$total=(int)$db->scalar('SELECT COUNT(*) FROM `'.$table.'` WHERE '.$conditions,$params);$p=max(1,(int)($_GET['p']??1));
$sortFields=array_values(array_intersect(array_column($readCols,'Field'),['name','code','reference','starts_at','created_at','sku','plate','happened_at']));$sort=in_array($_GET['sort']??'',$sortFields,true)?$_GET['sort']:'id';
$records=$db->all('SELECT * FROM `'.$table.'` WHERE '.$conditions.' ORDER BY `'.$sort.'` '.(($_GET['dir']??'desc')==='asc'?'ASC':'DESC').' LIMIT 20 OFFSET '.(($p-1)*20),$params);
$maps=[];foreach($foreign as $key=>$parent){$used=array_values(array_unique(array_filter(array_column($records,$key))));$maps[$key]=$used?array_column($db->all('SELECT id,'.$catalog->labelSQL($parent).' label FROM `'.$parent.'` WHERE id IN ('.implode(',',array_fill(0,count($used),'?')).')',$used),'label','id'):[];}
$editing=!empty($_GET['edit'])?$db->one('SELECT * FROM `'.$table.'` WHERE id=?',[(int)$_GET['edit']]):[];
?>
<div class="page-heading"><div><p class="context">Données de l’entrepôt</p><h1><?= h(Catalog::TITLES[$table]) ?></h1><p>Gérez les fiches et leurs relations avec des références lisibles.</p></div></div>
<form class="filters" method="get"><input type="hidden" name="page" value="catalog"><?php $opts=[];foreach(Catalog::TITLES as $key=>$label){if($user['role']!=='admin'&&in_array($key,['user_account','audit_log'],true))continue;if($user['role']==='gate'&&!in_array($key,['carrier','driver','vehicle','equipment','qualification','driver_qualification','vehicle_equipment','dock','dock_equipment','dock_vehicle_type','appointment','truck_visit','visit_event','dock_downtime'],true))continue;$opts[]=['id'=>$key,'label'=>$label];}selectField('t','Rubrique',$opts,$table);inputField('q','Rechercher',$_GET['q']??'','search',false);foreach($foreign as $key=>$parent)selectField('f_'.$key,Catalog::LABELS[$key]??$key,$catalog->options($parent),$_GET['f_'.$key]??'',true);selectField('sort','Trier par',array_map(fn($k)=>['id'=>$k,'label'=>Catalog::LABELS[$k]??$k],$sortFields),$_GET['sort']??'',true);selectField('dir','Ordre',[['id'=>'asc','label'=>'Croissant'],['id'=>'desc','label'=>'Décroissant']],$_GET['dir']??'desc'); ?><button>Afficher</button><a href="<?= h(url(['page'=>'catalog','t'=>$table])) ?>">Réinitialiser</a></form>
<?php if($canWrite): ?><details class="panel editor" <?= $editing||isset($_GET['new'])?'open':'' ?>><summary><?= $editing?'Modifier la fiche':'Ajouter une fiche' ?></summary><?php startForm('save',['table'=>$table,'id'=>$editing['id']??'']); ?><div class="form-grid">
<?php foreach($catalog->editable($table) as $col){$key=$col['Field'];$value=$editing[$key]??$col['Default']??'';$optional=$col['Null']==='YES'||$col['Default']!==null;
 if(isset($foreign[$key]))selectField($key,Catalog::LABELS[$key]??$key,$catalog->options($foreign[$key],$value),$value,$col['Null']==='YES');
 elseif(str_starts_with($col['Type'],'enum(')){preg_match_all("/'([^']*)'/",$col['Type'],$m);selectField($key,Catalog::LABELS[$key]??$key,array_map(fn($v)=>['id'=>$v,'label'=>Catalog::VALUES[$v]??$v],$m[1]),$value);}
 elseif(str_starts_with($col['Type'],'tinyint'))selectField($key,Catalog::LABELS[$key]??$key,[['id'=>0,'label'=>'Non'],['id'=>1,'label'=>'Oui']],$value);
 else { $type=match(true){$col['Type']==='date'=>'date',$col['Type']==='datetime'=>'datetime-local',str_contains($key,'email')=>'email',preg_match('/^(int|decimal)/',$col['Type'])===1=>'number',default=>'text'};if($type==='datetime-local')$value=str_replace(' ','T',(string)$value);inputField($key,Catalog::LABELS[$key]??$key,$value,$type,!$optional);}
}if($table==='user_account')inputField('password',$editing?'Nouveau mot de passe (laisser vide pour conserver)':'Mot de passe','','password',!$editing); ?>
</div><button>Enregistrer</button><?php if($editing): ?><a class="button secondary" href="<?= h(url(['page'=>'catalog','t'=>$table])) ?>">Quitter la modification</a><?php endif; ?></form></details><?php endif; ?>
<section class="panel"><div class="table-scroll"><table><thead><tr><?php foreach($readCols as $c): ?><th scope="col"><?= h(Catalog::LABELS[$c['Field']]??$c['Field']) ?></th><?php endforeach; ?><?php if($canWrite): ?><th scope="col">Actions</th><?php endif; ?></tr></thead><tbody><?php foreach($records as $r): ?><tr><?php foreach($readCols as $c): $key=$c['Field'];$value=$r[$key]; ?><td><?php if(isset($foreign[$key]))echo h($value===null?'—':($maps[$key][$value]??'Référence hors sélection'));elseif(in_array($key,['status','role'],true))echo badge($value);elseif(str_starts_with($c['Type'],'tinyint'))echo $value?'Oui':'Non';else echo h($value??'—'); ?></td><?php endforeach; ?><?php if($canWrite): ?><td class="row-actions"><a href="<?= h(url(['page'=>'catalog','t'=>$table,'edit'=>$r['id']])) ?>">Modifier</a><?php if(!in_array($table,['appointment','user_account'],true)){startForm('delete',['table'=>$table,'id'=>$r['id']]); ?><button class="danger-link" data-confirm="Supprimer cette fiche inutilisée ?">Supprimer</button></form><?php }else{if($table==='appointment'&&$r['status']==='active'){startForm('cancel_appointment',['id'=>$r['id']]); ?><button class="danger-link" data-confirm="Annuler ce rendez-vous ?">Annuler</button></form><?php }} ?></td><?php endif; ?></tr><?php endforeach; ?></tbody></table></div><?php if(!$records): ?><p class="empty">Aucune fiche. Ajoutez-en une ou modifiez les critères.</p><?php endif;pagination($total,$p); ?></section>
<?php if(in_array($table,Catalog::READONLY,true)): ?><p class="muted">Historique protégé. Utilisez les actions des écrans opérationnels pour créer ou corriger une opération.</p><?php endif; ?>
